SELECT analytics_order_facts.payment_method, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2026 AND analytics_order_facts.month = 4 AND analytics_order_facts.region = 'West' AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'small_business' GROUP BY analytics_order_facts.payment_method ORDER BY gross_revenue DESC, analytics_order_facts.payment_method ASC LIMIT 12
